package com.techhouseblr.meshwav

import org.junit.Assert.*
import org.junit.Test

class NoiseTest {
    private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16).toByte() }
    private fun hex(b: ByteArray) = b.joinToString("") { "%02x".format(it) }

    /** Parses the vectors generated by the Rust side: [section] then key=hex lines. */
    private fun vectors(): Map<String, Map<String, String>> {
        val text = javaClass.getResource("/noise_v1.txt")!!.readText()
        val out = LinkedHashMap<String, MutableMap<String, String>>()
        var cur: MutableMap<String, String>? = null
        for (line in text.lines()) {
            if (line.startsWith("#") || line.isBlank()) continue
            if (line.startsWith("[")) { cur = LinkedHashMap(); out[line.trim('[', ']')] = cur; continue }
            val (k, v) = line.split("=", limit = 2)
            cur!![k] = v
        }
        return out
    }

    @Test fun x25519MatchesRfc7748() {
        val aPriv = hex("77076d0a7318a57d3c16c17251b26645df4c2f87ebc0992ab177fba51db92c2a")
        val a = X25519.publicKey(aPriv)
        assertEquals("8520f0098930a754748b7ddcb43ef75a0dbf3a0d26381af4eba4a98eaa9b4e6a", hex(a))
        val bPriv = hex("5dab087e624a8a4b79e17f8b83800ee66f3bb1292618b6fd1c2f8b27ff88e0eb")
        val b = X25519.publicKey(bPriv)
        assertEquals("de9edb7d7b7dc1b4d35b61c2ece435373f8343c85b78674dadfc7e146f882b4f", hex(b))
        val shared = X25519.dh(aPriv, b)
        assertEquals("4a5d9d5ba4ce2de1728e3bf480350f25e07e21c947d19e3376f09b3c1e161742", hex(shared))
        assertArrayEquals(shared, X25519.dh(bPriv, a))
    }

    @Test fun x25519MatchesRfcScalarMultVector() {
        val out = X25519.scalarMult(
            hex("a546e36bf0527c9d3b16154b82465edd62144c0ac1fc5a18506a2244ba449ac4"),
            hex("e6db6867583030db3594c1a424b15f7c726624ec26b3353b10a903a6d0ab1c4c"),
        )
        assertEquals("c3da55379de9c6908e94ea4df28d084f32eccf03491c71f754b4075577a28552", hex(out))
    }

    @Test fun lowOrderPointIsRejected() {
        assertThrows(IllegalArgumentException::class.java) { X25519.dh(ByteArray(32) { 7 }, ByteArray(32)) }
    }

    private fun replay(section: String) {
        val v = vectors().getValue(section)
        val psk = v.getValue("psk").takeIf { it.isNotEmpty() }?.let(::hex)
        val n = NoiseInitiator(
            hex(v.getValue("initiator_static_private")), psk,
            hex(v.getValue("responder_static_public")),
            hex(v.getValue("initiator_ephemeral_private")),
        )
        assertEquals("msg1", v.getValue("msg1"), hex(n.writeMsg1()))
        val rs = n.readMsg2(hex(v.getValue("msg2")))
        assertEquals(v.getValue("responder_static_public"), hex(rs))
        assertEquals("msg3", v.getValue("msg3"), hex(n.writeMsg3(String(hex(v.getValue("device_name"))))))
        val (toAgent, toReceiver) = n.split()
        assertEquals("key_to_agent", v.getValue("key_to_agent"), hex(toAgent))
        assertEquals("key_to_receiver", v.getValue("key_to_receiver"), hex(toReceiver))
    }

    @Test fun xxMatchesRustVector() = replay("Noise_XX_25519_ChaChaPoly_SHA256")
    @Test fun xxPsk3MatchesRustVector() = replay("Noise_XXpsk3_25519_ChaChaPoly_SHA256")

    @Test fun pinMismatchIsFatal() {
        val v = vectors().getValue("Noise_XX_25519_ChaChaPoly_SHA256")
        val n = NoiseInitiator(hex(v.getValue("initiator_static_private")), null, ByteArray(32) { 1 }, hex(v.getValue("initiator_ephemeral_private")))
        n.writeMsg1()
        val e = assertThrows(HandshakeException::class.java) { n.readMsg2(hex(v.getValue("msg2"))) }
        assertTrue(e.fatal)
    }

    @Test fun tamperedOrShortMsg2IsRejected() {
        val v = vectors().getValue("Noise_XX_25519_ChaChaPoly_SHA256")
        val n = NoiseInitiator(hex(v.getValue("initiator_static_private")), null, null, hex(v.getValue("initiator_ephemeral_private")))
        n.writeMsg1()
        val bad = hex(v.getValue("msg2")).also { it[40] = (it[40].toInt() xor 1).toByte() }
        assertThrows(HandshakeException::class.java) { n.readMsg2(bad) }
        val m = NoiseInitiator(ByteArray(32) { 1 }, null, null).also { it.writeMsg1() }
        assertThrows(HandshakeException::class.java) { m.readMsg2(ByteArray(10)) }
    }

    @Test fun pairingPskMatchesRustDerivation() {
        val v = vectors().getValue("Noise_XXpsk3_25519_ChaChaPoly_SHA256")
        assertEquals(v.getValue("psk"), hex(Handshake.pairingPsk(hex(v.getValue("responder_static_public")), "123456")))
    }

    @Test fun codeValidation() {
        assertTrue(Handshake.validCode("012345"))
        for (c in listOf("", "12345", "1234567", "12345a", " 12345", "١٢٣٤٥٦")) assertFalse(c, Handshake.validCode(c))
    }

    @Test fun frameLayoutMatchesRust() {
        val f = Handshake.frame(Handshake.KIND_XXPSK3, 0x01020304, 1, byteArrayOf(9, 9))
        assertEquals("4d5701" + "11" + "01020304" + "01" + "0909", hex(f))
        val reply = Handshake.frame(Handshake.KIND_XXPSK3, 0x01020304, 2, byteArrayOf(5))
        assertArrayEquals(byteArrayOf(5), Handshake.parseReply(reply, reply.size, Handshake.KIND_XXPSK3, 0x01020304))
        assertNull(Handshake.parseReply(reply, reply.size, Handshake.KIND_XX, 0x01020304))
        assertNull(Handshake.parseReply(reply, reply.size, Handshake.KIND_XXPSK3, 7))
        assertNull(Handshake.parseReply(f, f.size, Handshake.KIND_XXPSK3, 0x01020304)) // step 1 is not a reply
    }
}
